# Initialize the to-do list and reminders dictionary
to_do_list = {}
reminders = {}

def add_task(task, reminder=False):
    """Add a task to the to-do list with an optional reminder."""
    if task in to_do_list:
        print(f"Task '{task}' already exists. Please choose another task.")
        return

    to_do_list[task] = reminder

    if reminder:
        reminders[task] = input(f"Enter the reminder time (e.g., '5m' for 5 minutes): ")

def manage_to_do_list():
    """Manage the to-do list with reminders based on user input."""
    while True:
        command = input("Enter a command (add, list, remove, quit): ").lower()

        if command == "add":
            task = input("Enter the task: ")
            add_task(task)

        elif command == "list":
            print("Current tasks:")
            for task, reminder in to_do_list.items():
                print(f"- {task} ({'with reminder' if reminder else ''} reminder: {reminders.get(task, 'no reminder')})")

        elif command == "remove":
            task = input("Enter the task to remove: ")
            if task in to_do_list:
                del to_do_list[task]
                if task in reminders:
                    del reminders[task]
                print(f"Task '{task}' removed.")

        elif command == "quit":
            print("Goodbye!")
            break

        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    manage_to_do_list()
```

This program will prompt the user for a command (add, list, remove, or quit) and then execute the corresponding function. The `add_task` function adds a task to the to-do list with an optional reminder, and the `manage_to_do_list` function manages the to-do list based on user input.
